//! Replays stable-observation fixtures from tests/fixtures through the tracker,
//! rule selection, and solve progress. The fixtures are synthetic: they are
//! generated by `tools/ijlo_solves.py fixtures` from the verified rule data.

use std::path::PathBuf;

use pc_overlay_core::{
    CommitOutcome, Observation, Piece, RuleSet, SessionTracker, SolveProgress, TrackerConfig,
    empty_board, evaluate_solve_progress,
};
use serde::Deserialize;

#[derive(Deserialize)]
struct Fixture {
    setup_id: String,
    steps: Vec<Step>,
}

#[derive(Deserialize)]
struct Step {
    label: String,
    pc: u8,
    board: Vec<String>,
    hold: Option<char>,
    current: char,
    next: String,
    pieces_left: Option<usize>,
    setup_left: Option<usize>,
    #[serde(default)]
    rollback: bool,
}

fn piece(code: char) -> Piece {
    match code {
        'I' => Piece::I,
        'J' => Piece::J,
        'L' => Piece::L,
        'O' => Piece::O,
        'S' => Piece::S,
        'T' => Piece::T,
        'Z' => Piece::Z,
        other => panic!("unknown piece {other}"),
    }
}

impl Step {
    fn observation(&self) -> Observation {
        let mut board = empty_board();
        for (y, row) in self.board.iter().enumerate() {
            for (x, code) in row.chars().enumerate() {
                if code != '.' {
                    board[y][x] = Some(piece(code));
                }
            }
        }
        let next: Vec<Piece> = self.next.chars().map(piece).collect();
        Observation {
            board,
            hold: self.hold.map(piece),
            current: piece(self.current),
            next5: next.try_into().expect("five NEXT pieces"),
        }
    }
}

fn replay(name: &str) {
    let root = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    let fixture: Fixture = serde_json::from_str(
        &std::fs::read_to_string(root.join("tests/fixtures").join(name)).unwrap(),
    )
    .unwrap();
    let rules = RuleSet::load(root.join("data/ijlo.json")).unwrap();
    let setup = rules
        .setup("ijlo_source_method", &fixture.setup_id)
        .expect("fixture setup exists");
    let solve = &setup.solves[0].target;

    let mut tracker = SessionTracker::new(TrackerConfig::default());
    let mut selected_at = None;
    for (index, step) in fixture.steps.iter().enumerate() {
        let observation = step.observation();
        let outcome = tracker.commit(observation.clone(), 1.0, index as u64);
        let label = &step.label;
        assert_eq!(
            matches!(outcome, CommitOutcome::RolledBack { .. }),
            step.rollback,
            "{label}: {outcome:?}"
        );
        assert!(
            matches!(
                outcome,
                CommitOutcome::Accepted { .. } | CommitOutcome::RolledBack { .. }
            ),
            "{label}: {outcome:?}"
        );
        assert_eq!(tracker.pc_ordinal().get(), step.pc, "{label}");
        if step.pc != 2 {
            continue;
        }

        let context = tracker
            .following_bag_context()
            .expect("PC 2 start observed");
        let selection = rules
            .select_for_board(&context, &observation.board)
            .selected
            .map(|selected| selected.setup_id);
        if selected_at.is_some() {
            assert_eq!(
                selection.as_deref(),
                Some(fixture.setup_id.as_str()),
                "{label}: guidance must persist through the setup and the solve"
            );
        } else if let Some(selected) = selection {
            assert_eq!(selected, fixture.setup_id, "{label}");
            selected_at = Some(index);
        }
        if step.setup_left == Some(0) {
            assert!(
                selected_at.is_some(),
                "{label}: setup finished without guidance"
            );
        }

        let progress = evaluate_solve_progress(&setup.placements, solve, &observation.board);
        if step.board.is_empty() {
            assert_eq!(progress, SolveProgress::Ambiguous, "{label}");
            continue;
        }
        let SolveProgress::InProgress { progress, .. } = progress else {
            panic!("{label}: {progress:?}");
        };
        assert_eq!(
            progress.missing_cells().count(),
            4 * step.pieces_left.unwrap(),
            "{label}"
        );
    }
    let last = fixture.steps.last().unwrap();
    assert_eq!(last.pc, 3, "the replay ends with the 2nd PC cleared");
    assert!(selected_at.is_some());
}

#[test]
fn s_queue_setup_and_solve_with_undo() {
    replay("ijlo_s_queue_with_undo.json");
}

#[test]
fn z_queue_setup_waits_for_z_then_solves_with_an_s_spin() {
    replay("ijlo_z_queue.json");
}

#[test]
fn save_o_left_is_chosen_when_both_queue_setups_fail() {
    replay("ijlo_save_o_left.json");
}

#[test]
fn save_o_right_is_chosen_when_only_it_can_be_solved() {
    replay("ijlo_save_o_right.json");
}
